const TOKEN_OPTIONS:Record<string,readonly string[]>={gap:['none','xs','s','m','l','xl','2xl'],spacing:['none','xs','s','m','l','xl','2xl'],align:['start','center','end','stretch','left','right'],justify:['start','center','end','between'],width:['full','content','narrow'],tone:['background','surface','muted','primary','text'],direction:['vertical','horizontal'],fit:['cover','contain'],loading:['lazy','eager'],radius:['none','s','m','l','pill'],variant:['primary','secondary','ghost'],size:['s','m','l'],layout:['horizontal','vertical']};
