const normalize=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,'');
const humanize=(value:string)=>value.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[._:-]+/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase());
const pageLabel=(page:Pick<StorefrontBuilderPageListItem,'pageKey'|'pageType'>|Pick<StorefrontPageDocument,'pageKey'|'pageType'>)=>PAGE_LABELS[normalize(page.pageType||page.pageKey)]??humanize(page.pageType||page.pageKey);
const fieldLabel=(key:string)=>FIELD_LABELS[normalize(key)]??humanize(key);
const optionLabel=(value:string)=>OPTION_LABELS[value]??humanize(value);
const componentLabel=(key:string)=>COMPONENT_LABELS[key]??humanize(key.split('.').at(-1)??key);
const componentGroup=(key:string)=>{const value=key.toLowerCase();if(value.includes('scene')||value.includes('recipe')||value.includes('release')||value.includes('shop-the-look')||value.includes('finder'))return'Interaktív';if(value.includes('product')||value.includes('collection')||value.includes('cart')||value.includes('checkout')||value.includes('recommend')||value.includes('commerce'))return'Kereskedelem';if(value.includes('image')||value.includes('gallery')||value.includes('video')||value.includes('media')||value.includes('visual'))return'Média';if(value.includes('navigation')||value.includes('menu')||value.includes('header')||value.includes('footer'))return'Navigáció';if(value.includes('review')||value.includes('testimonial')||value.includes('story')||value.includes('editorial')||value.includes('blog')||value.includes('text')||value.includes('heading'))return'Tartalom';if(value.includes('hero')||value.includes('banner')||value.includes('section')||value.includes('container')||value.includes('button')||value.includes('grid')||value.includes('stack'))return'Alap elemek';return'Egyéb';};
const componentIcon=(key:string):VisualBuilderIconName=>{const value=key.toLowerCase();if(value.includes('hero')||value.includes('banner')||value.includes('section')||value.includes('grid'))return'layout';if(value.includes('product')||value.includes('collection')||value.includes('commerce'))return'box';if(value.includes('review')||value.includes('testimonial'))return'star';if(value.includes('newsletter')||value.includes('email'))return'mail';if(value.includes('faq'))return'help';if(value.includes('image')||value.includes('gallery')||value.includes('video')||value.includes('visual'))return'image';if(value.includes('navigation')||value.includes('menu')||value.includes('header'))return'menu';if(value.includes('text')||value.includes('copy')||value.includes('heading'))return'text';if(value.includes('button')||value.includes('cta'))return'plus';return'component';};
const responsiveModeLabel=(mode:string)=>mode==='fixed'?'Rögzített':mode==='grid'?'Rugalmas rács':mode==='stack'?'Egymás alá':'Reszponzív';
const operationKey=(kind:string)=>`builder-v3:${kind}:${crypto.randomUUID()}`;
const statusLabel=(status:StorefrontFidelityInspectorStatus)=>status==='ok'?'Rendben':status==='warning'?'Figyelmeztetés':'Javítandó';
const statusFromIssues=(issues:readonly {severity:'warning'|'error'}[]):StorefrontFidelityInspectorStatus=>issues.some(issue=>issue.severity==='error')?'error':issues.length?'warning':'ok';

function flatten(document:StorefrontPageDocument){const result:FlatNode[]=[];const walk=(nodes:StorefrontComponentNode[],parentId:string|null,depth:number)=>nodes.forEach((node,index)=>{result.push({node,parentId,index,depth});walk(node.children??[],node.id,depth+1);});walk(document.sections,null,0);return result;}
function getNode(document:StorefrontPageDocument,id:string|null){return id?flatten(document).find(item=>item.node.id===id)?.node??null:null;}
function setNested(value:unknown,path:(string|number)[],next:unknown):unknown{if(!path.length)return next;const[head,...tail]=path;if(Array.isArray(value)){const copy=[...value];copy[Number(head)]=setNested(copy[Number(head)],tail,next);return copy;}const source=value&&typeof value==='object'?value as Record<string,unknown>:{};return{...source,[String(head)]:setNested(source[String(head)],tail,next)};}
function blankLike(value:unknown):unknown{if(typeof value==='string')return'';if(typeof value==='number')return 0;if(typeof value==='boolean')return false;if(Array.isArray(value))return[];if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value as Record<string,unknown>).map(([key,child])=>[key,blankLike(child)]));return null;}
function listSeed(componentKey:string,key:string,value:unknown):unknown|null{if(Array.isArray(value)&&value.length)return blankLike(value[0]);if(componentKey==='system.header'&&key==='utilityItems')return{label:'Új művelet',href:'/',symbol:'↗'};if(componentKey==='system.navigation'&&key==='items')return{label:'Új menüpont',href:'/'};return null;}

function BoundField({label,value}:{label:string;value:unknown}){const display=Array.isArray(value)?`${value.length} elem`:value&&typeof value==='object'?'Központi beállítás':value===null||value===undefined||value===''?'Nincs megadva':String(value);return <div className={v3.boundField}><div className={v3.boundHead}><span>{fieldLabel(label)}</span><b className={v3.badge}>Webshop adat</b></div><div className={v3.boundValue}>{display}</div><small>Központi webshop-adatból érkezik; itt szándékosan csak olvasható.</small></div>;}

function FieldEditor({label,value,onChange,itemTemplate}:{label:string;value:unknown;onChange:(value:unknown)=>void;itemTemplate?:unknown|null}){
  if(Array.isArray(value)){
    const seed=itemTemplate??(value.length?blankLike(value[0]):null);
    const moveItem=(from:number,to:number)=>{if(to<0||to>=value.length)return;const next=[...value];const[item]=next.splice(from,1);next.splice(to,0,item);onChange(next);};
    return <div className={v3.objectGroup}><div className={v3.sectionHead}><div><strong>{fieldLabel(label)}</strong><small>{value.length} elem</small></div>{seed!==null?<button type="button" className={v3.softButton} onClick={()=>onChange([...value,structuredClone(seed)])}><VisualBuilderIcon name="plus"/> Új elem</button>:null}</div>{value.length?value.map((item,index)=><div className={v3.objectGroup} key={index}><div className={v3.sectionHead}><div><strong>{index+1}. elem</strong><small>Sorrend és tartalom szerkeszthető.</small></div><div className={v3.tokenGrid}><button type="button" disabled={index===0} onClick={()=>moveItem(index,index-1)} aria-label="Feljebb"><VisualBuilderIcon name="chevron-up"/></button><button type="button" disabled={index===value.length-1} onClick={()=>moveItem(index,index+1)} aria-label="Lejjebb"><VisualBuilderIcon name="chevron-down"/></button><button type="button" onClick={()=>onChange(value.filter((_,itemIndex)=>itemIndex!==index))}>Eltávolítás</button></div></div><FieldEditor label="érték" value={item} onChange={next=>onChange(setNested(value,[index],next))}/></div>):<div className={v3.emptyCard}>Nincs beállított elem.{seed!==null?' Az „Új elem” gombbal azonnal hozzáadhatsz egyet.':' Ehhez az elemhez nincs biztonságos üres sablon definiálva.'}</div>}</div>;
  }
  if(value&&typeof value==='object')return <div className={v3.objectGroup}><strong>{fieldLabel(label)}</strong>{Object.entries(value as Record<string,unknown>).map(([key,child])=><FieldEditor key={key} label={key} value={child} onChange={next=>onChange(setNested(value,[key],next))}/>)}</div>;
  if(typeof value==='boolean')return <label className={v3.switch}><span>{fieldLabel(label)}</span><input type="checkbox" checked={value} onChange={event=>onChange(event.target.checked)}/></label>;
  if(typeof value==='number')return <label className={v3.field}><span>{fieldLabel(label)}</span><input type="number" value={value} onChange={event=>onChange(Number(event.target.value))}/></label>;
  const stringValue=typeof value==='string'?value:'';const options=TOKEN_OPTIONS[label];
  if(options&&options.length<=7)return <div className={v3.field}><span>{fieldLabel(label)}</span><div className={v3.tokenGrid}>{options.map(option=><button type="button" key={option} data-active={stringValue===option} onClick={()=>onChange(option)}>{optionLabel(option)}</button>)}</div></div>;
  if(options)return <label className={v3.field}><span>{fieldLabel(label)}</span><select value={stringValue} onChange={event=>onChange(event.target.value)}><option value="">—</option>{options.map(option=><option key={option} value={option}>{optionLabel(option)}</option>)}</select></label>;
  const multiline=label.toLowerCase().includes('copy')||label.toLowerCase().includes('text')||label.toLowerCase().includes('description')||stringValue.length>80;
  return <label className={v3.field}><span>{fieldLabel(label)}</span>{multiline?<textarea value={stringValue} rows={4} onChange={event=>onChange(event.target.value)}/>:<input value={stringValue} onChange={event=>onChange(event.target.value)}/>}</label>;
}

function Layers({document,viewport,selectedId,onSelect,onMove}:{document:StorefrontPageDocument;viewport:StorefrontViewport;selectedId:string|null;onSelect:(id:string)=>void;onMove:(nodeId:string,parentId:string|null,index:number)=>void}){
  const items=flatten(document);const[dragging,setDragging]=useState<string|null>(null);const[collapsed,setCollapsed]=useState<Set<string>>(()=>new Set());const parentOf=(id:string)=>items.find(item=>item.node.id===id)?.parentId??null;const visible=(entry:FlatNode)=>{let parent=entry.parentId;while(parent){if(collapsed.has(parent))return false;parent=parentOf(parent);}return true;};const toggle=(id:string)=>setCollapsed(current=>{const next=new Set(current);next.has(id)?next.delete(id):next.add(id);return next;});const drop=(event:DragEvent,entry:FlatNode)=>{event.preventDefault();if(dragging&&dragging!==entry.node.id)onMove(dragging,entry.parentId,entry.index);setDragging(null);};
  return <div className={v3.layers}><div className={v3.pageRoot}><VisualBuilderIcon name="page"/><strong>Oldal</strong><small>{pageLabel(document)}</small></div>{items.filter(visible).map(entry=>{const definition=componentRegistry.get(entry.node.componentKey,entry.node.componentVersion);const linked=findStorefrontLinkedSymbolInstance(document,entry.node.id);const protectedNode=definition?.protectedSystem===true;const hidden=entry.node.responsive?.[viewport]?.hidden===true;const hasChildren=Boolean(entry.node.children?.length);return <div key={entry.node.id} className={v3.layerRow} data-selected={selectedId===entry.node.id} style={{paddingLeft:4+entry.depth*11}} draggable={!protectedNode} onDragStart={()=>setDragging(entry.node.id)} onDragEnd={()=>setDragging(null)} onDragOver={event=>event.preventDefault()} onDrop={event=>drop(event,entry)}>{hasChildren?<button type="button" className={v3.disclosure} aria-label={collapsed.has(entry.node.id)?'Kibontás':'Összecsukás'} onClick={()=>toggle(entry.node.id)}><VisualBuilderIcon name={collapsed.has(entry.node.id)?'chevron-right':'chevron-down'}/></button>:<span/>}<button type="button" className={v3.layerMain} onClick={()=>onSelect(entry.node.id)}><VisualBuilderIcon name="grip"/><VisualBuilderIcon name={componentIcon(entry.node.componentKey)}/><span><strong>{componentLabel(entry.node.componentKey)}</strong><small>{entry.depth===0?'Szekció':entry.node.children?.length?'Konténer / komponens':'Komponens'}</small></span></button><span className={v3.layerBadges}>{linked?<b>Kapcsolt</b>:null}{protectedNode?<b>Védett</b>:null}{hidden?<b>Rejtett</b>:null}</span></div>;})}</div>;
}

export function StorefrontVisualBuilderV3({pages,document:initialDocument,pageId,draftRevision:initialDraftRevision,publishedRevision:initialPublishedRevision,revisions,capability,bindingContext,templates,savedBlocks}:Props){
  const router=useRouter();const[busy,startTransition]=useTransition();const[history,setHistory]=useState<StorefrontBuilderHistory|null>(()=>initialDocument?createStorefrontBuilderHistory(initialDocument):null);const[selectedId,setSelectedId]=useState<string|null>(()=>initialDocument?.sections[0]?.id??null);const[viewport,setViewport]=useState<StorefrontViewport>('desktop');const[panel,setPanel]=useState<PanelMode>('pages');const[tab,setTab]=useState<InspectorTab>('content');const[leftCollapsed,setLeftCollapsed]=useState(false);const[inspectorOpen,setInspectorOpen]=useState(Boolean(initialDocument?.sections[0]));const[draftRevision,setDraftRevision]=useState(initialDraftRevision);const[publishedRevision,setPublishedRevision]=useState(initialPublishedRevision);const[dirty,setDirty]=useState(false);const[notice,setNotice]=useState<string|null>(null);const[error,setError]=useState<string|null>(null);const[historyOpen,setHistoryOpen]=useState(false);const[publishOpen,setPublishOpen]=useState(false);const[componentQuery,setComponentQuery]=useState('');const[componentFilter,setComponentFilter]=useState('Összes');const[pageQuery,setPageQuery]=useState('');const[zoom,setZoom]=useState(100);const canvasRef=useRef<HTMLElement|null>(null);const pageFrameRef=useRef<HTMLDivElement|null>(null);const[pageFrameHeight,setPageFrameHeight]=useState(0);
  const document=history?.present??null;const selected=document?getNode(document,selectedId):null;const definition=selected?componentRegistry.get(selected.componentKey,selected.componentVersion):undefined;const viewportWidth=VIEWPORTS.find(item=>item.key===viewport)?.width??1200;const canvasFrameGeometry=resolveStorefrontBuilderCanvasFrameGeometry(viewportWidth,zoom);const entitled=(template:TemplateEntry)=>hasStorefrontRuntimeCapability({minPlan:template.minPlan,features:template.requiredFeatures as readonly FeatureCode[]},capability);
  const rawBrand=bindingContext.brand&&typeof bindingContext.brand==='object'&&!Array.isArray(bindingContext.brand)?bindingContext.brand as Record<string,unknown>:{};const brandName=typeof rawBrand.name==='string'?rawBrand.name:'';const editorBindingContext:Record<string,unknown>={...bindingContext,brand:{...rawBrand,homeHref:typeof rawBrand.homeHref==='string'?rawBrand.homeHref:'/',copyright:typeof rawBrand.copyright==='string'?rawBrand.copyright:(brandName?`© ${brandName}`:'')}};
  useEffect(()=>{if(!notice)return;const timer=window.setTimeout(()=>setNotice(null),3600);return()=>window.clearTimeout(timer);},[notice]);
  useEffect(()=>{const frame=pageFrameRef.current;if(!frame){setPageFrameHeight(0);return;}const update=()=>setPageFrameHeight(frame.offsetHeight);update();if(typeof ResizeObserver==='undefined')return;const observer=new ResizeObserver(update);observer.observe(frame);return()=>observer.disconnect();},[document,viewport]);
  const fitCanvas=()=>{const canvas=canvasRef.current;if(!canvas)return;const computed=window.getComputedStyle(canvas);const horizontalPadding=(Number.parseFloat(computed.paddingLeft)||0)+(Number.parseFloat(computed.paddingRight)||0);const available=Math.max(1,canvas.clientWidth-horizontalPadding);setZoom(resolveStorefrontBuilderFitZoom(viewportWidth,available));};
  if(!document)return <div className={v3.shell}><div className={v3.emptySelection}><strong>Nincs szerkeszthető oldal</strong><p>Válassz vagy telepíts sablont a sablonkönyvtárból.</p></div></div>;

  const applyMutation=(base:StorefrontPageDocument,mutation:StorefrontBuilderMutation)=>applyStorefrontBuilderMutation({document:base,mutation,registry:componentRegistry,capability});
  const commitDocument=(next:StorefrontPageDocument)=>{setHistory(current=>current?pushStorefrontBuilderHistory(current,next):current);setDirty(true);setError(null);};
  const mutate=(mutation:StorefrontBuilderMutation)=>{try{commitDocument(applyMutation(document,mutation));}catch(reason){setError(reason instanceof Error?reason.message:'A módosítás nem hajtható végre.');}};
  const setMerchantConfig=(key:string,value:unknown)=>{if(!selected)return;try{let next=applyMutation(document,{type:'config',nodeId:selected.id,key,value});const reference=selected.bindings?.[key];if(reference&&Object.prototype.hasOwnProperty.call(reference,'fallback'))next=applyMutation(next,{type:'binding',nodeId:selected.id,slot:key,path:reference.path,fallback:value});commitDocument(next);}catch(reason){setError(reason instanceof Error?reason.message:'A módosítás nem hajtható végre.');}};
  const applyFidelity=(next:StorefrontPageDocument,message:string)=>{commitDocument(next);setNotice(message);};
  const run=(job:()=>Promise<void>)=>startTransition(()=>{setError(null);setNotice(null);job().catch(reason=>setError(reason instanceof Error?reason.message:'A művelet sikertelen.'));});
  const move=(nodeId:string,parentId:string|null,index:number)=>mutate({type:'move',nodeId,parentId,index});
  const save=()=>run(async()=>{const result=await saveVisualBuilderDraftAction({document,expectedDraftRevision:draftRevision,operationKey:operationKey('save')});setDraftRevision(result.revisionNumber);setDirty(false);setNotice(`Mentve · r${result.revisionNumber}`);router.refresh();});
  const preview=()=>{if(!pageId||!draftRevision)return;run(async()=>{if(dirty)throw new Error('Mentsd a módosításokat az előnézet előtt.');const result=await createVisualBuilderPreviewAction({pageId,revisionNumber:draftRevision,operationKey:operationKey('preview')});window.open(`${result.href}?viewport=${viewport}`,'_blank','noopener,noreferrer');});};
  const publish=()=>{if(!pageId||!draftRevision)return;run(async()=>{if(dirty)throw new Error('Mentsd a módosításokat a közzététel előtt.');const result=await publishVisualBuilderPageAction({pageId,expectedDraftRevision:draftRevision,operationKey:operationKey('publish')});setPublishedRevision(result.revisionNumber);setPublishOpen(false);setNotice(`Közzétéve · r${result.revisionNumber}`);router.refresh();});};
  const rollback=(target:number)=>{if(!pageId||!publishedRevision)return;run(async()=>{const result=await rollbackVisualBuilderPageAction({pageId,targetPublishedRevision:target,expectedCurrentPublishedRevision:publishedRevision,operationKey:operationKey('rollback')});setPublishedRevision(result.revisionNumber);setNotice(`Visszaállítva · r${result.revisionNumber}`);router.refresh();});};
  const install=(template:TemplateEntry)=>run(async()=>{const result=await installVisualBuilderTemplateAction({templateKey:template.templateKey,templateVersion:template.templateVersion,operationKey:operationKey('template')});setNotice(`${result.templateKey} telepítve · ${result.pageCount} oldal`);router.refresh();});

  const flat=flatten(document);const fidelity=inspectStorefrontFidelityBuilder(document);const advancedMode=fidelity.editMode!=='normal';const selectedFlat=selected?flat.find(entry=>entry.node.id===selected.id)??null:null;const effectiveConfig=selected?applyStorefrontBindings(selected,editorBindingContext):{};const externallyBound=(key:string)=>{const reference=selected?.bindings?.[key];return Boolean(reference&&resolveStorefrontBinding(reference.path,editorBindingContext)!==undefined);};const allConfigurable=[...(definition?.manifest.configurable??[])];const configurable=allConfigurable.filter(key=>advancedMode||!HIDDEN_NORMAL_KEYS.has(normalize(key)));const contentKeys=configurable.filter(key=>!SIMPLE_APPEARANCE_KEYS.has(key)&&!DELEGATED_KEYS.has(key));const appearanceKeys=configurable.filter(key=>SIMPLE_APPEARANCE_KEYS.has(key));const variants=selected?listStorefrontComponentVariants(componentRegistry,selected):[];const activeVariant=selected?detectStorefrontComponentVariant(componentRegistry,selected):null;const insertableSelected=selected?listStorefrontBuilderInsertableComponents({document,registry:componentRegistry,capability,parentId:selected.id}):[];const insertableRoot=listStorefrontBuilderInsertableComponents({document,registry:componentRegistry,capability,parentId:null});const insertable=[...insertableRoot,...insertableSelected.filter(candidate=>!insertableRoot.some(root=>root.componentKey===candidate.componentKey&&root.componentVersion===candidate.componentVersion))];const visibleInsertable=insertable.filter(item=>{const query=componentQuery.trim().toLowerCase();return(!query||`${item.componentKey} ${componentLabel(item.componentKey)}`.toLowerCase().includes(query))&&(componentFilter==='Összes'||componentGroup(item.componentKey)===componentFilter);});const visiblePages=pages.filter(page=>!pageQuery.trim()||`${pageLabel(page)} ${page.pageType}`.toLowerCase().includes(pageQuery.trim().toLowerCase()));const activeResponsive=selected?.responsive?.[viewport];const responsiveOverrideActive=Boolean(activeResponsive&&(activeResponsive.hidden===true||activeResponsive.gridSpan!==undefined));

  const selectNode=(id:string)=>{setSelectedId(id);setInspectorOpen(true);setTab('content');};
  const addComponent=(item:{componentKey:string;componentVersion:number},parentId:string|null)=>{const nodeId=`${item.componentKey.replace(/[^a-z0-9._:-]+/gi,'-')}-${crypto.randomUUID().slice(0,8)}`.toLowerCase().slice(0,127);mutate({type:'add',parentId,componentKey:item.componentKey,componentVersion:item.componentVersion,nodeId});setSelectedId(nodeId);setInspectorOpen(true);setTab('content');};
  const renderField=(key:string)=>{const fieldValue=effectiveConfig[key]??selected?.config[key]??'';return externallyBound(key)?<BoundField key={key} label={key} value={effectiveConfig[key]}/>:<FieldEditor key={key} label={key} value={fieldValue} itemTemplate={listSeed(selected?.componentKey??'',key,fieldValue)} onChange={value=>setMerchantConfig(key,value)}/>;};
  const applyVariant=(variantId:string)=>{if(!selected)return;try{commitDocument(applyStorefrontComponentVariant(document,{nodeId:selected.id,variantId},componentRegistry));setNotice('Megjelenési variáns alkalmazva.');}catch(reason){setError(reason instanceof Error?reason.message:'A variáns nem alkalmazható.');}};
  const changeMode=(mode:StorefrontBuilderEditMode)=>applyFidelity(setStorefrontFidelityEditMode(document,mode),`${mode==='normal'?'Normál':mode==='advanced'?'Haladó':'Expert'} mód bekapcsolva.`);
  const pageStatus=(page:StorefrontBuilderPageListItem)=>page.draftRevision?`Piszkozat · r${page.draftRevision}`:page.publishedRevision?`Közzétett · r${page.publishedRevision}`:'Nincs mentett változat';

  const viewportStatus=(target:StorefrontViewport):StorefrontFidelityInspectorStatus=>{const issues=fidelity.layout.issues.filter(issue=>issue.viewport===target);return issues.some(issue=>issue.severity==='error')?'error':issues.length?'warning':'ok';};const imageIssues=fidelity.accessibility.issues.filter(issue=>issue.code.startsWith('ACCESSIBILITY_IMAGE_'));const linkIssues=fidelity.accessibility.issues.filter(issue=>issue.code.includes('HREF')||issue.code.includes('CONTROL_LABEL'));const contentIssues=fidelity.accessibility.issues.filter(issue=>issue.code.includes('HEADING'));const readiness=[{label:'Mentett piszkozat',status:(dirty||!draftRevision?'error':'ok') as StorefrontFidelityInspectorStatus,detail:dirty?'A módosításokat még menteni kell.':draftRevision?`Aktuális piszkozat: r${draftRevision}`:'Nincs mentett piszkozat.'},...VIEWPORTS.map(item=>({label:`${item.label} nézet`,status:viewportStatus(item.key),detail:viewportStatus(item.key)==='ok'?'Nincs ismert overflow vagy clipping probléma.':'Elrendezési diagnosztika jelzett problémát.'})),{label:'Akadálymentesség',status:fidelity.accessibility.status,detail:fidelity.accessibility.issues.length?`${fidelity.accessibility.issues.length} jelzés található.`:'Nincs ismert akadálymentességi probléma.'},{label:'Képek',status:statusFromIssues(imageIssues),detail:imageIssues.length?`${imageIssues.length} képes jelzés.`:'A kötelező képleírások rendben.'},{label:'Linkek',status:statusFromIssues(linkIssues),detail:linkIssues.length?`${linkIssues.length} hivatkozás-jelzés.`:'A hivatkozások diagnosztikája rendben.'},{label:'Kötelező tartalmak',status:statusFromIssues(contentIssues),detail:contentIssues.length?`${contentIssues.length} címsor-jelzés.`:'A címsor-hierarchia rendben.'},{label:'Teljesítmény',status:fidelity.performance.status,detail:fidelity.performance.issues.length?`${fidelity.performance.issues.length} teljesítményjelzés.`:'A dokumentum a teljesítménykereten belül van.'},{label:'Design Guard',status:(fidelity.designGuard.mode==='off'?'warning':'ok') as StorefrontFidelityInspectorStatus,detail:fidelity.designGuard.mode==='off'?'A Design Guard ki van kapcsolva.':`Design Guard: ${fidelity.designGuard.mode}.`}];const readinessErrors=readiness.filter(item=>item.status==='error').length;const readinessWarnings=readiness.filter(item=>item.status==='warning').length;

  const canvasDecorator=(node:StorefrontResolvedComponentNode,rendered:ReactNode)=>{const entry=flat.find(item=>item.node.id===node.id);const nodeDefinition=componentRegistry.get(node.componentKey,node.componentVersion);const protectedNode=nodeDefinition?.protectedSystem===true;const active=selectedId===node.id;return <div className={v3.node} data-selected={active} data-builder-node-id={node.id} style={resolveStorefrontBuilderCanvasPlacement(node,viewport)} onClick={event=>{event.stopPropagation();selectNode(node.id);}}>{active?<><span className={v3.nodeLabel}>{componentLabel(node.componentKey)}{protectedNode?' · védett':''}</span><div className={v3.floatingTools} onClick={event=>event.stopPropagation()}><button type="button" title="Tartalom" onClick={()=>setTab('content')}><VisualBuilderIcon name="edit"/></button><button type="button" title="Felfelé" disabled={!entry||entry.index===0||protectedNode} onClick={()=>entry&&move(node.id,entry.parentId,Math.max(0,entry.index-1))}><VisualBuilderIcon name="chevron-up"/></button><button type="button" title="Lefelé" disabled={!entry||protectedNode} onClick={()=>entry&&move(node.id,entry.parentId,entry.index+1)}><VisualBuilderIcon name="chevron-down"/></button><button type="button" title="Duplikálás" disabled={protectedNode} onClick={()=>mutate({type:'duplicate',nodeId:node.id})}><VisualBuilderIcon name="duplicate"/></button><button type="button" title="Elrendezés" onClick={()=>setTab('layout')}><VisualBuilderIcon name="eye"/></button><button type="button" title="Megjelenés" onClick={()=>setTab('appearance')}><VisualBuilderIcon name="settings"/></button><button type="button" title="Törlés" disabled={protectedNode} onClick={()=>{mutate({type:'remove',nodeId:node.id});setSelectedId(null);setInspectorOpen(false);}}><VisualBuilderIcon name="trash"/></button></div>{!protectedNode?<button type="button" className={v3.insertHandle} title="Blokk hozzáadása" onClick={event=>{event.stopPropagation();setPanel('add');setLeftCollapsed(false);}}><VisualBuilderIcon name="plus"/></button>:null}</>:null}{rendered}</div>;};

  return <div className={v3.shell}>
    <header className={v3.topbar}>
      <div className={v3.brand}><span className={v3.brandMark}>S</span><span className={v3.brandText}><strong>Shoperation</strong><small>Visual Builder</small></span></div>
      <Link className={v3.adminBack} href="/admin"><VisualBuilderIcon name="arrow-left"/> Vissza az Admin felületre</Link>
      <label className={v3.pageSelect}><span className={v3.srOnly}>Szerkesztett oldal</span><select value={document.pageKey} onChange={event=>router.push(`/admin/tartalom/builder?page=${encodeURIComponent(event.target.value)}`)}>{pages.map(page=><option key={page.pageId} value={page.pageKey}>{pageLabel(page)}</option>)}</select></label>
      <div className={v3.viewSwitch} role="group" aria-label="Szerkesztési nézet">{VIEWPORTS.map(item=><button key={item.key} type="button" data-active={viewport===item.key} aria-pressed={viewport===item.key} onClick={()=>setViewport(item.key)}><VisualBuilderIcon name={item.icon}/>{item.label}</button>)}</div>
      <div className={v3.topActions}><button type="button" className={v3.iconButton} title="Bal panel" onClick={()=>setLeftCollapsed(value=>!value)}><VisualBuilderIcon name="panel-menu"/></button><button type="button" className={v3.iconButton} title="Inspector" onClick={()=>setInspectorOpen(value=>!value)}><VisualBuilderIcon name="panel-right"/></button><button type="button" className={v3.iconButton} title="Visszavonás" disabled={busy||!history?.past.length} onClick={()=>{setHistory(current=>current?undoStorefrontBuilderHistory(current):current);setDirty(true);}}><VisualBuilderIcon name="undo"/></button><button type="button" className={v3.iconButton} title="Újra" disabled={busy||!history?.future.length} onClick={()=>{setHistory(current=>current?redoStorefrontBuilderHistory(current):current);setDirty(true);}}><VisualBuilderIcon name="redo"/></button><span className={v3.saveState}>{dirty?'Nem mentett':draftRevision?`Mentve · r${draftRevision}`:'Piszkozat'}</span><button type="button" className={v3.softButton} disabled={busy||!dirty} onClick={save}>Mentés</button><button type="button" className={v3.softButton} onClick={()=>setHistoryOpen(true)}><VisualBuilderIcon name="history"/> Előzmények</button><button type="button" className={v3.softButton} disabled={busy||dirty||!draftRevision} onClick={preview}><VisualBuilderIcon name="eye"/> Előnézet</button><button type="button" className={v3.primaryButton} disabled={busy||!draftRevision} onClick={()=>setPublishOpen(true)}><VisualBuilderIcon name="upload"/> Közzététel</button></div>
    </header>

    {error?<div className={v3.error} role="alert">{error}</div>:null}{notice?<div className={v3.notice} role="status"><VisualBuilderIcon name="check"/><span>{notice}</span><button type="button" aria-label="Bezárás" onClick={()=>setNotice(null)}><VisualBuilderIcon name="close"/></button></div>:null}

    <div className={v3.workspace} data-left-collapsed={leftCollapsed} data-inspector-open={inspectorOpen}>
      <aside className={v3.left} data-collapsed={leftCollapsed}>
        <nav className={v3.primaryNav} aria-label="Visual Builder fő navigáció">{([['pages','pages','Oldalak'],['add','plus','Hozzáadás'],['structure','layers','Rétegek'],['templates','templates','Sablonok'],['presets','presets','Presetek'],['saved','saved','Saját blokkok'],['globals','globals','Globális elemek']] as const).map(([mode,icon,label])=><button key={mode} type="button" data-active={panel===mode} onClick={()=>{setPanel(mode);setLeftCollapsed(false);}}><VisualBuilderIcon name={icon}/>{label}</button>)}</nav>
        <div className={v3.panelBody}>
          {panel==='pages'?<><div className={v3.panelHead}><div><strong>Oldalak</strong><span>A webshop szerkeszthető oldalai.</span></div></div><input className={v3.search} type="search" value={pageQuery} onChange={event=>setPageQuery(event.target.value)} placeholder="Oldal keresése…"/><div className={v3.pageList}>{visiblePages.map(page=><Link key={page.pageId} data-active={page.pageKey===document.pageKey} href={`/admin/tartalom/builder?page=${encodeURIComponent(page.pageKey)}`}><span className={v3.pageListIcon}><VisualBuilderIcon name={page.pageKey===document.pageKey?'home':'page'}/></span><span><strong>{pageLabel(page)}</strong><small>{pageStatus(page)}</small></span></Link>)}</div></>:null}
          {panel==='add'?<><div className={v3.panelHead}><div><strong>Hozzáadás</strong><span>Csak az ezen az oldalon ténylegesen engedélyezett blokkok jelennek meg.</span></div></div><input className={v3.search} value={componentQuery} onChange={event=>setComponentQuery(event.target.value)} placeholder="Blokk keresése…"/><div className={v3.filterRow}>{['Összes','Alap elemek','Tartalom','Média','Navigáció','Kereskedelem','Interaktív','Egyéb'].map(filter=><button type="button" key={filter} data-active={componentFilter===filter} onClick={()=>setComponentFilter(filter)}>{filter}</button>)}</div>{selected&&insertableSelected.length?<div className={v3.insertTarget}><span>Beszúrási cél</span><strong>{componentLabel(selected.componentKey)}</strong><small>A kompatibilis blokkok a kijelölt elembe kerülhetnek.</small></div>:null}<div className={v3.componentGrid}>{visibleInsertable.map(item=>{const inSelected=Boolean(selected&&insertableSelected.some(candidate=>candidate.componentKey===item.componentKey&&candidate.componentVersion===item.componentVersion));const atRoot=insertableRoot.some(candidate=>candidate.componentKey===item.componentKey&&candidate.componentVersion===item.componentVersion);return <article className={v3.componentCard} key={`${item.componentKey}@${item.componentVersion}`}><div className={v3.componentPreview}><VisualBuilderIcon name={componentIcon(item.componentKey)}/></div><div className={v3.componentMeta}><strong>{componentLabel(item.componentKey)}</strong><small>{componentGroup(item.componentKey)} · {responsiveModeLabel(item.responsiveMode)}</small></div><div className={v3.componentActions}>{inSelected?<button type="button" onClick={()=>addComponent(item,selected?.id??null)}>Beillesztés ide</button>:atRoot?<button type="button" onClick={()=>addComponent(item,null)}>Hozzáadás</button>:null}</div></article>;})}</div>{!visibleInsertable.length?<div className={v3.emptyCard}>Nincs a szűrésnek megfelelő, ide beilleszthető blokk.</div>:null}</>:null}
          {panel==='structure'?<><div className={v3.panelHead}><div><strong>Rétegek</strong><span>Oldal → Szekció → Konténer → Komponens.</span></div></div><Layers document={document} viewport={viewport} selectedId={selectedId} onSelect={selectNode} onMove={move}/></>:null}
          {panel==='templates'?<div className={v3.panelBridge}><div className={v3.panelHead}><div><strong>Sablonok</strong><span>Teljes oldal vagy webshop kiindulópont.</span></div></div><StorefrontPageTemplatesPanel document={document} capability={capability} onApply={(next,nodeId,message)=>{applyFidelity(next,message);setSelectedId(nodeId);setInspectorOpen(true);}}/><button type="button" className={v3.softButton} onClick={()=>router.push('/admin/tartalom/builder?view=templates')}><VisualBuilderIcon name="templates"/> Teljes sablonkönyvtár</button></div>:null}
          {panel==='presets'?<div className={v3.panelBridge}><StorefrontPresetLibraryPanel document={document} selectedNode={selected} capability={capability} onApply={(next,nodeId,message)=>{applyFidelity(next,message);setSelectedId(nodeId);setInspectorOpen(true);}}/></div>:null}
          {panel==='saved'?<div className={v3.panelBridge}><StorefrontSavedBlocksPanel document={document} selectedNode={selected} selectedIsTopLevel={selectedFlat?.parentId===null} initialSavedBlocks={savedBlocks} capability={capability} onApply={(next,insertedNodeId,message)=>{applyFidelity(next,message);setSelectedId(insertedNodeId);setInspectorOpen(true);setTab('content');}}/></div>:null}
          {panel==='globals'?<div className={v3.panelBridge}><div className={v3.panelHead}><div><strong>Globális elemek és stílusok</strong><span>Színek, tipográfia, komponensvariánsok, Design Guard és oldal-szintű diagnosztika.</span></div></div><StorefrontFidelitySettings document={document} viewport={viewport} onApply={applyFidelity}/></div>:null}
        </div>
      </aside>

      <main ref={canvasRef} className={v3.canvas} onClick={event=>{if(event.target===event.currentTarget){setSelectedId(null);setInspectorOpen(false);}}}>
        <div className={v3.canvasTools}><div className={v3.canvasToolsInner}><button type="button" aria-label="Kicsinyítés" onClick={()=>setZoom(value=>Math.max(STOREFRONT_BUILDER_MIN_ZOOM,value-10))}>−</button><b>{zoom}%</b><button type="button" aria-label="Nagyítás" onClick={()=>setZoom(value=>Math.min(STOREFRONT_BUILDER_MAX_ZOOM,value+10))}>+</button><button type="button" onClick={fitCanvas}>Fit</button><button type="button" onClick={()=>setZoom(100)}>100</button></div></div>
        <div className={v3.breakpoint}><VisualBuilderIcon name={viewport==='desktop'?'desktop':viewport==='tablet'?'tablet':'mobile'}/><span>{viewport==='desktop'?'Desktop':viewport==='tablet'?'Tablet':'Mobil'} · {viewportWidth}px</span><b>{selected?(responsiveOverrideActive?'Egyedi override':'Örökölt'):'Élő nézet'}</b></div>
        <div className={v3.pageFrameViewport} style={{width:canvasFrameGeometry.scaledWidth,height:pageFrameHeight?Math.ceil(pageFrameHeight*canvasFrameGeometry.scale):undefined}}><div ref={pageFrameRef} className={v3.pageFrame} data-viewport={viewport} style={{width:canvasFrameGeometry.width,transform:canvasFrameGeometry.transform,transformOrigin:'top left',margin:0}}><StorefrontRuntimeRenderer page={document} viewport={viewport} bindingContext={editorBindingContext} componentRegistry={componentRegistry} rendererRegistry={rendererRegistry} capability={capability} decorateNode={canvasDecorator}/></div></div>
      </main>

      <aside className={v3.inspector} data-open={inspectorOpen}>
        {selected&&definition?<><div className={v3.inspectorHead}><div className={v3.selectionIdentity}><span className={v3.selectionIcon}><VisualBuilderIcon name={componentIcon(selected.componentKey)}/></span><span><strong>{componentLabel(selected.componentKey)}</strong><small>{definition.protectedSystem?'Védett rendszer elem':componentGroup(selected.componentKey)}</small></span></div><div className={v3.modeSwitch}>{(['normal','advanced','expert'] as const).map(mode=><button type="button" key={mode} data-active={fidelity.editMode===mode} onClick={()=>changeMode(mode)}>{mode==='normal'?'Normál':mode==='advanced'?'Haladó':'Expert'}</button>)}</div></div><nav className={v3.inspectorTabs} aria-label="Inspector navigáció"><button type="button" data-active={tab==='content'} onClick={()=>setTab('content')}>Tartalom</button><button type="button" data-active={tab==='appearance'} onClick={()=>setTab('appearance')}>Megjelenés</button><button type="button" data-active={tab==='layout'} onClick={()=>setTab('layout')}>Elrendezés</button><button type="button" data-active={tab==='states'} onClick={()=>setTab('states')}>Állapotok</button><button type="button" data-active={tab==='advanced'} onClick={()=>setTab('advanced')}>Haladó</button></nav><div className={v3.inspectorBody}>
          {tab==='content'?<><section className={v3.section}><div className={v3.sectionHead}><div><strong>Tartalom</strong><small>A kijelölt elem tényleges kereskedői tartalma.</small></div></div>{contentKeys.length?contentKeys.map(renderField):<div className={v3.emptyCard}>Ennek az elemnek nincs külön tartalmi mezője. A megjelenés, elrendezés és állapotok a többi fülön állíthatók.</div>}</section>{selected.componentKey==='system.header'?<section className={v3.section}><div className={v3.sectionHead}><div><strong>Fejléc vezérlés</strong><small>A márkanév és márkalink központi webshop-adat. Sticky, variáns, scroll-állapot és reszponzív viselkedés a megfelelő füleken szerkeszthető.</small></div><b className={v3.badge}>Védett</b></div><div className={v3.quickGrid}><button type="button" onClick={()=>setTab('appearance')}>Megjelenés</button><button type="button" onClick={()=>setTab('states')}>Sticky / scroll</button><button type="button" onClick={()=>setTab('layout')}>Mobil / layout</button><button type="button" onClick={()=>setPanel('globals')}>Globális stílusok</button></div></section>:null}</>:null}
          {tab==='appearance'?<><section className={v3.section}><div className={v3.sectionHead}><div><strong>Gyors megjelenés</strong><small>A leggyakoribb vizuális döntések, biztonságos tokenekkel.</small></div></div>{appearanceKeys.length?appearanceKeys.map(renderField):<div className={v3.emptyCard}>Nincs egyszerű megjelenési token ezen az elemen.</div>}</section>{variants.length?<section className={v3.section}><div className={v3.sectionHead}><div><strong>Komponens variánsok</strong><small>Gyári vizuális irányok ugyanazon canonical komponenshez.</small></div></div><div className={v3.variantGrid}>{variants.map(variant=><button type="button" className={v3.variantCard} data-active={activeVariant?.variantId===variant.variantId} key={variant.variantId} onClick={()=>applyVariant(variant.variantId)}><strong>{variant.label}</strong><small>{variant.description}</small></button>)}</div></section>:null}<div className={v3.panelBridge}><StorefrontFidelityNodeControls document={document} node={selected} viewport={viewport} configurable={allConfigurable} onApply={applyFidelity}/></div></>:null}
          {tab==='layout'?<><section className={v3.section}><div className={v3.sectionHead}><div><strong>Reszponzív nézet</strong><small>Desktop → Tablet → Mobil öröklés ugyanazon Page Schema dokumentumban.</small></div></div><div className={v3.responsiveSummary}>{VIEWPORTS.map(item=><button type="button" key={item.key} data-active={viewport===item.key} onClick={()=>setViewport(item.key)}><b>{item.label}</b><small>{item.key==='desktop'?'Alap':item.key==='tablet'?'Desktopból örököl':'Tablet/desktop öröklés'}</small></button>)}</div></section><div className={v3.panelBridge}><StorefrontResponsiveLayoutDepthControls document={document} node={selected} viewport={viewport} responsiveMode={definition.manifest.responsiveMode} supportsStyle={allConfigurable.includes('style')} onApply={applyFidelity}/></div></>:null}
          {tab==='states'?<div className={v3.panelBridge}><section className={v3.section}><div className={v3.sectionHead}><div><strong>Interakció és viselkedés</strong><small>Hover, focus, active, disabled, sticky scroll és más támogatott állapotok.</small></div></div></section><StorefrontFidelityStateControls document={document} node={selected} viewport={viewport} configurable={allConfigurable} onApply={applyFidelity}/></div>:null}
          {tab==='advanced'?<><section className={v3.section}><div className={v3.sectionHead}><div><strong>Komponens meta</strong><small>Technikai információk és destruktív műveletek.</small></div></div><div className={v3.objectGroup}><small>Azonosító</small><strong>{selected.id}</strong><small>Komponens</small><strong>{selected.componentKey}</strong><small>Responsive mód</small><strong>{responsiveModeLabel(definition.manifest.responsiveMode)}</strong><small>Csomag</small><strong>{definition.manifest.capability.minPlan}</strong></div><div className={v3.quickGrid}><button type="button" disabled={definition.protectedSystem} onClick={()=>mutate({type:'duplicate',nodeId:selected.id})}>Duplikálás</button><button type="button" disabled={definition.protectedSystem} onClick={()=>{mutate({type:'remove',nodeId:selected.id});setSelectedId(null);setInspectorOpen(false);}}>Eltávolítás</button></div></section>{advancedMode?<section className={v3.section}><div className={v3.sectionHead}><div><strong>Haladó szerkesztés</strong><small>A nyers stílusobjektumok helyett továbbra is a közös, sanitizerrel védett Builder-kontrollokat használjuk.</small></div></div><div className={v3.emptyCard}>A vizuális style, typography, state és responsive authority a Megjelenés / Elrendezés / Állapotok füleken érhető el. Nincs párhuzamos JSON-szerkesztő.</div></section>:<div className={v3.emptyCard}>Haladó és Expert módban további szerkesztési mélység jelenik meg.</div>}</>:null}
        </div></>:<div className={v3.emptySelection}><VisualBuilderIcon name="pointer"/><strong>Válassz ki egy elemet</strong><p>Kattints a vásznon vagy a Rétegek panelen egy komponensre. Itt jelennek meg a hozzá tartozó kereskedőbarát beállítások.</p></div>}
      </aside>
    </div>

    {historyOpen?<div className={v3.drawerBackdrop} onClick={()=>setHistoryOpen(false)}><aside className={v3.drawer} onClick={event=>event.stopPropagation()}><header className={v3.drawerHeader}><div><span>Előzmények</span><strong>Verziók és közzétételek</strong></div><button type="button" onClick={()=>setHistoryOpen(false)}><VisualBuilderIcon name="close"/></button></header><div className={v3.drawerBody}><div className={v3.historyList}>{revisions.filter(item=>item.kind==='published').map(item=><article key={item.revisionId}><div><strong>r{item.revisionNumber}</strong><time>{new Date(item.createdAt).toLocaleString('hu-HU')}</time></div><button type="button" disabled={item.revisionNumber===publishedRevision} onClick={()=>rollback(item.revisionNumber)}>{item.revisionNumber===publishedRevision?'Aktuális':'Visszaállítás'}</button></article>)}</div></div><footer className={v3.drawerFoot}><button type="button" className={v3.softButton} onClick={()=>setHistoryOpen(false)}>Bezárás</button></footer></aside></div>:null}
    {publishOpen?<div className={v3.drawerBackdrop} onClick={()=>setPublishOpen(false)}><aside className={v3.drawer} onClick={event=>event.stopPropagation()}><header className={v3.drawerHeader}><div><span>Közzététel</span><strong>Közzététel előtti ellenőrzés</strong></div><button type="button" onClick={()=>setPublishOpen(false)}><VisualBuilderIcon name="close"/></button></header><div className={v3.drawerBody}><div className={v3.section}><div className={v3.sectionHead}><div><strong>{readinessErrors?'Még van javítandó pont':readinessWarnings?'Közzétehető, de van figyelmeztetés':'Készen áll a közzétételre'}</strong><small>{readinessErrors} javítandó · {readinessWarnings} figyelmeztetés</small></div></div></div><div className={v3.readiness}>{readiness.map(item=><article key={item.label} data-status={item.status}><span><VisualBuilderIcon name={item.status==='ok'?'check':item.status==='warning'?'warning':'error'}/></span><div><strong>{item.label}</strong><small>{item.detail}</small></div><b>{statusLabel(item.status)}</b></article>)}</div></div><footer className={v3.drawerFoot}><button type="button" className={v3.softButton} onClick={()=>setPublishOpen(false)}>Mégse</button><button type="button" className={v3.primaryButton} disabled={busy||dirty||!draftRevision||readinessErrors>0} onClick={publish}>Közzététel</button></footer></aside></div>:null}
  </div>;
}
